                best = p
        return best

    obs = observation if isinstance(observation, dict) else {}
    env = obs.get("environment_name", "") or ""
    role = obs.get("self_role", "") or ""

    me = pt(obs.get("self_position"), (0, 0))
    opp = pt(obs.get("opponent_position"), me)

