    unclaimed = as_points(obs.get("unclaimed_cells", []))
    opp_terr = as_points(obs.get("opponent_territory", []))
    own_terr = as_points(obs.get("self_territory", []))

    # Extra fallbacks for unknown schemas
    if not resources:
        resources = as_points(obs.get("food", []))
    if not unclaimed:
